using Microsoft.Dynamics365.LocalizationFramework;
using System.IO;

/// <summary>
/// MPJ_30779_PaymentPlus
/// <c>METERImportFormatSourceAzureStorageSettings</c> manages the settings for new ER source for 'MET Azure Storage'
/// </summary>
public class METERImportFormatSourceAzureStorageSettings implements SysPackable, ERIImportFileSourceSettings 
{
    internal const str SettingsKey = classStr(METERImportFormatSourceAzureStorageSettings);
    public const str Separator = ';';
    public const int CurrentVersion = 1;    
    private Set docuTypesSet;   
    private DocuTypeId archiveDocuTypeId;
    private DocuTypeId warningDocuTypeId;
    private DocuTypeId quarantineDocuTypeId;

    private boolean isEnabled;
    private boolean isDecrypted;

}

Method.Source:
public void new()
{
    docuTypesSet = new Set(Types::String);
}

[Hookable(false)]
public boolean parmIsEnabled(boolean _value = isEnabled)
{
    // this method is required for a serialization.
    isEnabled = _value;
    return isEnabled;
}

[Hookable(false)]
public void setEnabled(boolean _value)
{
    isEnabled = _value;
}

[Hookable(false)]
public boolean isEnabled()
{
    return isEnabled;
}

[Hookable(false)]
public DocuTypeId parmArchiveDocuTypeId(DocuTypeId _docuTypesId = archiveDocuTypeId)
{
    archiveDocuTypeId = _docuTypesId;
    return archiveDocuTypeId;
}

[Hookable(false)]
public DocuTypeId parmWarningDocuTypeId(DocuTypeId _docuTypesId = warningDocuTypeId)
{
    warningDocuTypeId = _docuTypesId;
    return warningDocuTypeId;
}

[Hookable(false)]
public DocuTypeId parmQuarantineDocuTypeId(DocuTypeId _docuTypesId = quarantineDocuTypeId)
{
    quarantineDocuTypeId = _docuTypesId;
    return quarantineDocuTypeId;
}

[Hookable(false)]
public boolean parmIsDecrypted(boolean _value = isDecrypted)
{
    // this method is required for a serialization.
    isDecrypted = _value;
    return isDecrypted;
}

private boolean hasSettingToMove(ERFormatFileDestinationAfterImport _destination)
{
    switch (_destination)
    {
        case ERFormatFileDestinationAfterImport::Archive:
            return archiveDocuTypeId != '';
        case ERFormatFileDestinationAfterImport::Warning:
            return warningDocuTypeId != '';
        case ERFormatFileDestinationAfterImport::Quarantine:
            return quarantineDocuTypeId != '';
    }
    return false;
}

/// <summary>
/// Retrieves a set of the docu types values.
/// </summary>
/// <returns>The set of the docu types values.</returns>
[Hookable(false)]
public Set getDocuTypesSet()
{
    return docuTypesSet;
}

[Hookable(false)]
public str getName()
{
    return "@MET:AzureStorage";
}

/// <summary>
/// Sets docu types values in string representation.
/// </summary>
/// <param name = "_values">A docu types values.</param>
[Hookable(false)]
public void setValues(str _values)
{
    docuTypesSet = new Set(Types::String);
    if (_values)
    {
        var enum = strSplit(_values, Separator).getEnumerator();
        while (enum.moveNext())
        {
            docuTypesSet.add(enum.current());
        }
    }
}

    /// <summary>
    /// Gets docu types values in string representation.
    /// </summary>
    /// <returns>A docu types values.</returns>
    [Hookable(false)]
    public str getValues()
    {
        str ret;
        var enum = docuTypesSet.getEnumerator();
        while(enum.moveNext())
        {
            ret += ret ? Separator : '';
            ret += enum.current();
        }

        return ret;
    }

/// <summary>
/// Validates the settings.
/// </summary>
/// <returns>True, if validated successful; otherwise - false.</returns>
[Hookable(false)]
public boolean validate()
{
    if (docuTypesSet.empty())
    {
        throw error("@MET:DocuTypeAzureStorageRequired");
    }
    return true;
}

/// <summary>
/// Gets a settings key, this key should starts with or be an implementation class name, also this key should be persistent and should not be changed over time.
/// This key will be used to retrieve this type of settings from a settings storage.
/// </summary>
/// <returns>The settings key.</returns>
[Hookable(false)]
public str getKey()
{
    return SettingsKey;
}

[Hookable(false)]
public container pack()
{
    return [CurrentVersion, docuTypesSet.pack(), archiveDocuTypeId, warningDocuTypeId, quarantineDocuTypeId, isEnabled, isDecrypted];
}

[Hookable(false)]
public boolean unpack(container packedClass)
{
    container packedSet;
    int version = RunBase::getVersion(packedClass);
    switch (version)
    {
        case CurrentVersion:
            [version, packedSet, archiveDocuTypeId, warningDocuTypeId, quarantineDocuTypeId, isEnabled, isDecrypted] = packedClass;
            docuTypesSet = Set::create(packedSet);
            return true;
        /*case 2:
            [version, packedSet, archiveDocuTypeId, warningDocuTypeId, quarantineDocuTypeId] = packedClass;
            docuTypesSet = Set::create(packedSet);
            return true;
        case 1:
            [version, packedSet] = packedClass;
            docuTypesSet = Set::create(packedSet);
            return true;*/
        default:
            return false;
    }
}

private ERIFileDestination createPostProcessingDestination(ERFormatFileDestinationAfterImport _destination, boolean _isDecrypted)
{
    DocuTypeId destinationDocuType;
    METERFileDestinationAzureStorage    metERFileDestinationAzureStorage;
    switch (_destination)
    {
        case ERFormatFileDestinationAfterImport::Archive:
            destinationDocuType = this.parmArchiveDocuTypeId();
            break;
        case ERFormatFileDestinationAfterImport::Warning:
            destinationDocuType =  this.parmWarningDocuTypeId();
            break;
        case ERFormatFileDestinationAfterImport::Quarantine:
            destinationDocuType = this.parmQuarantineDocuTypeId();
            break;
    }
    metERFileDestinationAzureStorage = new METERFileDestinationAzureStorage(destinationDocuType);
    metERFileDestinationAzureStorage.parmIsEncrypted(_isDecrypted);
    return metERFileDestinationAzureStorage;
}

/// <summary>
/// Creates a file source for current settings.
/// </summary>
/// <param name = "_fileMask">File mask.</param>
/// <returns>A new instance of a file source.</returns>
[Hookable(false)]
public ERIFileSource createFileSource(str _fileMask)
{
    return METERFileSourceAzureStorage::construct(this.getDocuTypesSet(), _fileMask, isDecrypted);
}

    /// <summary>
    /// Post processing for resulted file. An action after file importing.
    /// </summary>
    /// <param name = "_args">Arguments for file post import process.</param>
    [Hookable(false)]
    public void fileImported(ERFileImportedArgs _args)
    {
        var destination = _args.IsImportOperationSuccessful() ?
                            (_args.hasWarnings() ?
                                ERFormatFileDestinationAfterImport::Warning :
                                ERFormatFileDestinationAfterImport::Archive) :
                                ERFormatFileDestinationAfterImport::Quarantine;

        boolean movedSuccessfully, hasSettingToMove;
        if (this.isEnabled())
        {
            hasSettingToMove = this.hasSettingToMove(destination);
            if (hasSettingToMove)
            {
                // VNG missing ER DotNet Utils reference
                //var importFile = ERCast::asAny(_args.getFile()) as ERIImportFile;
                ERIImportFile importFile = _args.getFile();

                var name = importFile != null ? importFile.get_Name() : '';
                //movedSuccessfully = this.moveToSource(_args.getState(), destination, _args.getFileStream(), name);
                movedSuccessfully = this.moveToSource(_args, destination, name);
            }
        }

        ttsbegin;
        if (movedSuccessfully)
        {
            _args.getState().markAsMoved();
            //this.tryToDelete(_args.getState(), _args.getFile());
            this.tryToDelete(_args);
        }
        else if (!hasSettingToMove && destination != ERFormatFileDestinationAfterImport::Quarantine)
        {
            //this.tryToDelete(_args.getState(), _args.getFile());
            this.tryToDelete(_args);
        }
        ttscommit;
    }

//private boolean tryToDelete(ERImportFileSourceStateManager _stateManager, ERIFile _file)
private boolean tryToDelete(ERFileImportedArgs _args)
{
    boolean ret;
    if (_args.getFile())
    {
        ttsbegin;
        var result = _args.getFile().Delete();
        if (result.IsSuccess)
        {
            _args.getState().markAsDeleted();
            ret = true;
        }
        _args.getState().getLogger().logDeleted(!result.IsSuccess, result.ErrorMessage, '');
        ttscommit;
    }
    return ret;
}

private boolean moveToSource(
    ERFileImportedArgs _args,
    //ERImportFileSourceStateManager _stateManager,
    ERFormatFileDestinationAfterImport _destination,
    //Stream _fileStream, 
    str _fileName
)
{
    boolean ret;
    str errorMessage, description;
    //if (_fileStream)
    if (_args.getFileStream())
    {
        ERIFileDestinationWithResult fileDestination = this.createPostProcessingDestination(_destination, isDecrypted);
        ERFileSaveResult result = fileDestination.TrySaveFile(_args.getFileStream(),_fileName);
        ret = result.IsSuccess;
        description = result.Message;
        errorMessage = result.ErrorMessage;
    }
    if (!ret)
    {
        errorMessage = strFmt("@ElectronicReporting:FileCannotBeMoved", enum2Str(_destination)) + errorMessage;
    }
    _args.getState().getLogger().logMoved(!ret, errorMessage, description);
    return ret;
}

/// <summary>
/// Create new instance of <c>METERImportFormatSourceAzureStorageSettings</c> from packed presentation.
/// </summary>
/// <param name = "_packedClass">A container with packed presentation.</param>
/// <returns>New instance.</returns>
internal static METERImportFormatSourceAzureStorageSettings create(container _packedClass)
{
    var settings = new METERImportFormatSourceAzureStorageSettings();
    settings.unpack(_packedClass);
    return settings;
}
